#include "code_scan.h"
#include "checks_perf.h"
int check_pass_by_value(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_STRUCT&&f->tokens[i+1].type==TK_ID&&f->tokens[i+2].type==TK_ID){int j=i+3;while(j<f->ntokens){if(f->tokens[j].type==TK_LPAREN){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5001;snprintf(out->msg,sizeof(out->msg),"Large struct '%s' passed by value - use pointer instead",f->tokens[i+1].text);snprintf(out->suggestion,sizeof(out->suggestion),"Use const struct %s* instead of struct %s",f->tokens[i+1].text,f->tokens[i+1].text);}break;}j++;}}}return cnt;}
int check_unnecessary_copy(SourceFile*f,Project*p,Issue*out){int cnt=0;int i; for(i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_EQ&&f->tokens[i+2].type==TK_ID){char*dst=f->tokens[i].text;char*src=f->tokens[i+2].text;if(strcmp(dst,src)==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5002;snprintf(out->msg,sizeof(out->msg),"Self-assignment detected: %s = %s",dst,src);}}}}if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_EQ&&f->tokens[i+2].type==TK_LBRACE){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5002;snprintf(out->msg,sizeof(out->msg),"Struct copy from brace-enclosed initializer may be inefficient");}}return cnt;}
int check_loop_invariant(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-5;i++){if(f->tokens[i].type==TK_FOR||f->tokens[i].type==TK_WHILE){int depth=1;int j=i+1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){int body_depth=1;int k=j+1;int func_calls=0;while(k<f->ntokens&&body_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)body_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE)body_depth--;if(body_depth==0)break;if(f->tokens[k].type==TK_ID&&f->tokens[k+1].type==TK_LPAREN){TokenType callee_kind=lexer_is_type_keyword(f->tokens[k].text)?TK_UNKNOWN:TK_ID;func_calls++;}k++;}if(func_calls>5){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5003;snprintf(out->msg,sizeof(out->msg),"Loop with %d function calls - may be inefficient",func_calls);}}}}}return cnt;}
int check_inefficient_string(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-1;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN&&strcmp(f->tokens[i].text,"strlen")==0){int depth=1;int j=i+2;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}for(int k=j;k<f->ntokens-2&&k<j+5;k++){if(f->tokens[k].type==TK_LT||f->tokens[k].type==TK_GT||f->tokens[k].type==TK_FOR||f->tokens[k].type==TK_WHILE){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_PERFORMANCE;out->code=5004;snprintf(out->msg,sizeof(out->msg),"strlen() called in loop condition - recalculated each iteration");snprintf(out->suggestion,sizeof(out->suggestion),"Compute strlen once before the loop");}break;}}}}return cnt;}
int check_recursion(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){char*fname=f->tokens[i].text;int depth=1;int j=i+2;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){int body_depth=1;int k=j+1;while(k<f->ntokens&&body_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)body_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE)body_depth--;if(body_depth==0)break;if(f->tokens[k].type==TK_ID&&strcmp(f->tokens[k].text,fname)==0&&f->tokens[k+1].type==TK_LPAREN){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5005;snprintf(out->msg,sizeof(out->msg),"Recursive call to '%s' - check for base case",fname);}break;}k++;}}}}return cnt;}
int check_nested_loop(SourceFile*f,Project*p,Issue*out){int cnt=0;int loop_depth=0;int max_depth=0;int i; for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_FOR||f->tokens[i].type==TK_WHILE||f->tokens[i].type==TK_DO){loop_depth++;if(loop_depth>max_depth)max_depth=loop_depth;if(loop_depth>=3&&cnt<1&&out){cnt++;LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5006;snprintf(out->msg,sizeof(out->msg),"Nested loop depth %d - may have O(n^%d) complexity",loop_depth,loop_depth);snprintf(out->suggestion,sizeof(out->suggestion),"Consider optimizing nested loops or using better algorithms");}}if(f->tokens[i].type==TK_RBRACE||f->tokens[i].type==TK_BLOCK_CLOSE)loop_depth--;if(loop_depth<0)loop_depth=0;}return cnt>0?1:cnt;}
int check_redundant_branch(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_IF&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&f->tokens[j].type==TK_SEMI){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5007;snprintf(out->msg,sizeof(out->msg),"Empty if statement with no body");}}}}return cnt;}
int check_constant_loop(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-6;i++){if(f->tokens[i].type==TK_FOR&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;if(f->tokens[j].type==TK_SEMI&&f->tokens[j+1].type==TK_SEMI){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5008;snprintf(out->msg,sizeof(out->msg),"Infinite loop detected (for(;;))");snprintf(out->suggestion,sizeof(out->suggestion),"Ensure there's a break condition inside the loop");}}}}return cnt;}
int check_typedef_perf(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_TYPEDEF&&strstr(f->tokens[i].text,"struct")!=NULL){cnt++;}}return cnt>0?1:cnt;}
int check_volatile_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_VOLATILE){cnt++;}}if(cnt>10&&out){out->loc.line=0;out->sev=SEV_INFO;out->cat=CAT_PERFORMANCE;out->code=5010;snprintf(out->msg,sizeof(out->msg),"Excessive use of volatile (%d times) - may indicate design issues",cnt);snprintf(out->suggestion,sizeof(out->suggestion),"Use atomic operations or memory barriers where appropriate");return cnt;}return cnt>10?1:0;}
